# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# D-form instructions (VLEPEM Rev. 0 Chapter 3; EREF D form).

# CHECK: e_add16i 3, 4, 1 # encoding: [0x1c,0x64,0x00,0x01]
e_add16i 3, 4, 1
# CHECK: e_add16i 3, 4, -1 # encoding: [0x1c,0x64,0xff,0xff]
e_add16i 3, 4, -1
# CHECK: e_add16i 3, 0, 32767 # encoding: [0x1c,0x60,0x7f,0xff]
e_add16i 3, 0, 32767
# CHECK: e_add16i 3, 4, -32768 # encoding: [0x1c,0x64,0x80,0x00]
e_add16i 3, 4, -32768
# CHECK: e_lbz 3, 0(4) # encoding: [0x30,0x64,0x00,0x00]
e_lbz 3, 0(4)
# CHECK: e_lha 3, 0(4) # encoding: [0x38,0x64,0x00,0x00]
e_lha 3, 0(4)
# CHECK: e_lhz 3, 0(4) # encoding: [0x58,0x64,0x00,0x00]
e_lhz 3, 0(4)
# CHECK: e_lwz 3, -32768(4) # encoding: [0x50,0x64,0x80,0x00]
e_lwz 3, -32768(4)
# CHECK: e_lwz 3, 32767(0) # encoding: [0x50,0x60,0x7f,0xff]
e_lwz 3, 32767(0)
# CHECK: e_stb 3, 0(4) # encoding: [0x34,0x64,0x00,0x00]
e_stb 3, 0(4)
# CHECK: e_sth 3, 0(4) # encoding: [0x5c,0x64,0x00,0x00]
e_sth 3, 0(4)
# CHECK: e_stw 3, 4(1) # encoding: [0x54,0x61,0x00,0x04]
e_stw 3, 4(1)
